INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Annie', 'Female — Unknown', 'Annie is one of the playable characters in League of Legends. She is the daughter of Gregori and Amoline. The couple quickly suspected that there was something special about their daughter. When she was two years old, Annie miraculously bewitched a shadow bear and turned it into her pet. To this day she keeps her bear ''''Tibbers'''' by her side, often keeping him spellbound as a stuffed doll to be carried like a child''s toy. The combination of Annie''s lineage and the dark magic of her birthplace have given this little girl tremendous arcane power.
