INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('kate-marsh', 8294, 'https://images.igdb.com/igdb/image/upload/t_cover_big/kfrtejgmdn502jommmx6.jpg', '#0f172a', (SELECT id FROM genders WHERE igdb_id = 1), (SELECT id FROM species WHERE igdb_id = 1)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Kate Marsh', 'Female — Human', 'Kate Beverly Marsh is one of the students at Blackwell Academy in the game Life is Strange. She is a nice and kind-hearted, rather shy teenager who doesn''t like to be in the center of attention. She''s also constantly bullied for her conservative views on sex and religion, and is a strong Christian. After someone records and uploads a video that goes viral because of uncharacteristic behavior (due to Kate getting drugged), Kate becomes very depressed and thinks that the spread of the video is a form of punishment to weaken her faith. Thanks to this event, she stops smiling and constantly looks worried and sad.
INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('albert-wesker', 8297, 'https://images.igdb.com/igdb/image/upload/t_cover_big/t23zjj6ixuqasqtqvuvl.jpg', '#0f172a', NULL, (SELECT id FROM species WHERE igdb_id = 5)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Albert Wesker', 'Unknown', 'Albert Wesker is one of the central characters in the Resident Evil franchise by Capcom (or Biohazard in Japan). He was introduced in the original game and was the captain of U.S. police team STARS. Initially introduced as a supporting character in the first game, he has been one of the primary antagonists throughout the series, where he usually manipulates story events behind-the-scenes. 
