INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Draven', 'Unknown', 'Draven (from League of Legends) was never satisfied with victory in battle (unlike his brother, Darius). He wanted glory and recognition, seeking greatness in the Noxian military, However, they didn''t appreciate his drama. Wanting to share "Draven" with the world, he turned his attention to the prison system. There, he turned the tedious affair of executions into a spectacle.
