INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'David Young', 'Human', 'David Young is the main protagonist of D4: Dark Dreams Don''t Die. He is a young beat private investigator who is highly trained in the forensic arts. Working as a police officer of the Boston Police Department''s Narcotics Division, he soon met Peggy who he fell madly in love with. They got married and lived happily for a short period of time. Then one day, someone attacked Youngs'' home, shot David in the head and Peggy''s body was found drained of blood in the bathtub. Even though David somehow survived, the murder left him unable to recollect important memories. The only thing he remembers, was his wife''s dying word to "look for D". This incident caused him to gain a time traveling ability. After finding out about it, mixed together with Peggy''s murder case reaching a dead-end, he decided to quit the BPD to investigate the murder on his own. With the power, he uses mementos from past cases to try and solve the case by finding this mysterious "D".
