INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'David Anderson', 'Human', 'Captain David Edward Anderson is a human war hero and the original captain of the SSV Normandy. Anderson was born on June 8, 2137 to Ursula and Paul Anderson, a nurse and flight mechanic respectively, in the city of London on Earth, and was the last of three children by his parents'' second marriage. Anderson is one of the Alliance''s most decorated special forces operatives, and the first to graduate from the N7 marine program at Arcturus Station, serving with honor in the First Contact War.' FROM characters WHERE igdb_id = 104 ON CONFLICT (character_id, language_code) DO NOTHING;
