INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('the-pirate-king', 9723, 'https://images.igdb.com/igdb/image/upload/t_cover_big/bftymofmpkrayeggpj7y.jpg', '#0f172a', NULL, (SELECT id FROM species WHERE igdb_id = 5)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'The Pirate King', 'Unknown', 'In the game, Sea of Lies: Leviathan Reef, you meet the dastardly Pirate King. He is out for blood and quickly picks you as his next target. To get revenge against the player''s father, the infamous pirate has a plan involving kidnapping and hurting you. Instead of looking for you himself, he sends another captain who instead of kidnapping the player, lets them go. During the game, you have to find your way out of a mysterious island full of pirates, with no one to trust. The only way to stop the King of Pirates is by finding a way to stop the villain for good.
INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('aiden-pearce', 3729, 'https://images.igdb.com/igdb/image/upload/t_cover_big/byrpf4ukdwochtg7pjlm.jpg', '#0f172a', NULL, (SELECT id FROM species WHERE igdb_id = 1)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Aiden Pearce', 'Human', 'Aiden Pearce (also known as "The Vigilante" and "The Fox" by citizens and the media) is the protagonist of Watch Dogs. He is a highly skilled grey hat hacker who has access to the CTOS of Chicago using a highly specialized device, the Profiler. 
