INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Bowser', 'Unknown', 'Bowser (known as Koopa in Japan) is the main antagonist of the Super Mario series. He is the King of the Koopas, one of the races that live in the Mushroom World. He is always trying to capture Princess Peach, the Princess of the Mushroom Kingdom, but his plans are frustrated by Mario and Luigi.INSERT INTO character_games (character_id, game_id, is_primary) SELECT c.id, g.id, true FROM characters c, games g WHERE c.igdb_id = 12821 AND g.igdb_id = 26758 ON CONFLICT DO NOTHING;
