INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('emily-davis', 3848, 'https://images.igdb.com/igdb/image/upload/t_cover_big/kqnbdapuwy8ajpxqipow.jpg', '#0f172a', (SELECT id FROM genders WHERE igdb_id = 1), (SELECT id FROM species WHERE igdb_id = 1)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Emily Davis', 'Female — Human', 'Emily has a quick tongue and a sharp wit. She''s well-known within the group for her withering putdowns, but that does mean that she can come across as a bit of a bitch.
INSERT INTO character_games (character_id, game_id, is_primary) SELECT c.id, g.id, true FROM characters c, games g WHERE c.igdb_id = 3848 AND g.igdb_id = 533 ON CONFLICT DO NOTHING;
