INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('rosabeth-of-melfia', 856, 'https://images.igdb.com/igdb/image/upload/t_cover_big/mxnde0pvpyinuyn1zfgm.jpg', '#0f172a', (SELECT id FROM genders WHERE igdb_id = 1), (SELECT id FROM species WHERE igdb_id = 5)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Rosabeth of Melfia', 'Female — Unknown', 'Rosabeth of Melfia is a character in Dark Souls II and can be found near Majula, as a petrified statue who blocks the door to the Shaded Woods. Rosabeth is a very gifted pyromancy student and praises her teacher, a famed sorcerer. Getting fascinated by his sorceries, she went after him as he embarked on a journey. They ended up getting separated and Rosabeth tried to find her way back to him as she was attacked by a Basilisk. She managed to close the gate, but not before the monster used it''s breath on her, turning the girl into a stone statue.
