INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Altair', 'Human', 'Altaïr Ibn-La''Ahad is a fictional character in the Assassin''s Creed series. He serves as the protagonist of Assassin''s Creed, Assassin''s Creed: Altaïr''s Chronicles and Assassin''s Creed: Bloodlines. Altaïr also appears as a playable character in Assassin''s Creed: Revelations and is playable once in Assassin''s Creed II.' FROM characters WHERE igdb_id = 893 ON CONFLICT (character_id, language_code) DO NOTHING;
